const count = document.getElementById("count");
let n = 0;
document.getElementById("add").addEventListener("click", () => {
  n++;
  count.textContent = n;
});
document.getElementById("reset").addEventListener("click", () => {
  n = 0;
  count.textContent = n;
});

function convert(ksh, rate) {
  if (String(ksh).trim() === "" || String(rate).trim() === "") return "–";
  const k = Number(ksh), r = Number(rate);
  if (!Number.isFinite(k) || !Number.isFinite(r) || r === 0) return "–";
  return (k / r).toFixed(2) + " USD";
}

const kshBox = document.getElementById("ksh");
const rateBox = document.getElementById("rate");
const usd = document.getElementById("usd");
kshBox.addEventListener("input", () => {
  usd.textContent = convert(kshBox.value, rateBox.value);
});
